use verus::*;
use std::vec::Vec;

verus! {

fn append(a: &Vec<i32>, b: i32) -> Vec<i32>
    ensures
        |result: Vec<i32>| {
            result.len() == a.len() + 1
            && forall |i: usize| (i < a.len() ==> result[i] == a[i])
            && result[a.len()] == b
        }
{
    // Create a new vector to hold the result
    let mut res: Vec<i32> = Vec::new();

    // Push each element of the input vector to the result vector
    let mut i: usize = 0;
    while i < a.len() {
        invariant i <= a.len();
        invariant res.len() == i;
        invariant forall |j: usize| (j < i ==> res[j] == a[j]);
        {
            res.push(a[i]);
            i += 1;
        }
    }

    // Append the new element
    res.push(b);

    res
}

}